head.script:
scwin.onpageload = function() {
	pageList1.setCount(20);
	pageList2.setCount(20);
	pageList3.setCount(20);
};

scwin.checkVal1 = function() {
	const ck_class1 = (document.getElementById('pageList1') || document.getElementById('mf_pageList1')).classList.contains('w2pagination');
	const ck_class2 = (document.getElementById('pageList2') || document.getElementById('mf_pageList2')).classList.contains('w2pagination');
	const ck_class3 = (document.getElementById('pageList3') || document.getElementById('mf_pageList3')).classList.contains('w2pagination');
	return ck_class1 && ck_class2 && ck_class3;
};
